1	package registrymgr
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"log"
9		"net/http"
10		"net/url"
11		"strings"
12		"time"
13	
14		"github.com/anthnel/devdesk/internal/oci"
15	)
16	
17	func init() {
18		Register(&NexusDetector{})
19	}
20	
21	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
22	// Two URL formats are supported:
23	//  1. Path-based:   https://nexus.example.com/repository/docker-group
24	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
25	//
26	// Which one applies is read from the URL. Whether this detector runs at all is
27	// not: that is the declared provider's decision (§3.8, decision F).
28	type NexusDetector struct{}
29	
30	// maxNexusResponse bounds what one Nexus reply may take in memory. The replies
31	// are small JSON documents (a repository and the names of its members); the
32	// figure follows the reasoning of the catalog page cap and is not measured.
33	const maxNexusResponse = 1 << 20
34	
35	// nexusHTTPClient refuses a redirect to another origin, so the account of the
36	// registry is never sent to a host it was not given for.
37	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
38	
39	// Provider returns the provider this detector serves.
40	func (n *NexusDetector) Provider() string { return ProviderNexus }
41	
42	// DetectGroup calls the Nexus REST API to determine whether the registry points
43	// to a group repository and, if so, returns its member repositories.
44	//
45	// Returns nil, nil when the manager answered and the repository is not a group,
46	// and an error when it could not be asked. Those two are not the same thing:
47	// the caller caches the first and must not cache the second, or one unreachable
48	// minute erases what was last known (D23).
49	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
50		// Resolve which URL to use for the Nexus API call.
51		apiBase := info.ManagementURL
52		if apiBase == "" {
53			apiBase = info.URL
54		}
55	
56		host, repoName, err := parseNexusURL(apiBase)
57		if err != nil {
58			// Not an error: a URL that is not a Nexus repository path is a settled
59			// answer, not a failure to reach one.
60			// The cause only: a URL that does not parse may hold a password, and
61			// url.Error repeats it whole.
62			var ue *url.Error
63			if errors.As(err, &ue) {
64				err = ue.Err
65			}
66			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
67			return nil, nil
68		}
69	
70		hasAuth := info.Username != "" && info.Password != ""
71		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
72	
73		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
74		// and may already include memberNames in the attributes field (no admin privilege needed).
75		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
76		if err != nil {
77			return nil, err
78		}
79		if repoType != "group" {
80			return nil, nil
81		}
82	
83		if len(members) > 0 {
84			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
85			return members, nil
86		}
87	
88		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
89		// but returns memberNames reliably on Nexus instances that support it.
90		members = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
91		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
92		return members, nil
93	}
94	
95	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
96	// Returns type, format and any memberNames found in attributes, or an error when
97	// the manager could not be asked.
98	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
99	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
100		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
101		body, err := n.nexusGET(ctx, endpoint, info)
102		if err != nil {
103			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
104			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
105		}
106		var result struct {
107			Type   string `json:"type"`
108			Format string `json:"format"`
109			Group  struct {
110				MemberNames []string `json:"memberNames"`
111			} `json:"group"`
112			Attributes struct {
113				Group struct {
114					MemberNames []string `json:"memberNames"`
115				} `json:"group"`
116			} `json:"attributes"`
117		}
118		if err := json.Unmarshal(body, &result); err != nil {
119			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
120			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
121		}
122		log.Printf("INFO [registrymgr/nexus] meta %q: type=%s format=%s", repoName, result.Type, result.Format)
123	
124		// Collect memberNames from whichever field Nexus populated.
125		rawNames := result.Group.MemberNames
126		if len(rawNames) == 0 {
127			rawNames = result.Attributes.Group.MemberNames
128		}
129		members = memberList(info.URL, rawNames)
130		return result.Type, result.Format, members, nil
131	}
132	
133	// fetchGroupMembers calls the format-specific group endpoint which reliably
134	// includes memberNames: GET /v1/repositories/{format}/group/{name}
135	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
136	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
137		if format == "" {
138			format = "docker"
139		}
140		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
141		body, err := n.nexusGET(ctx, endpoint, info)
142		if err != nil {
143			// When auth is present but the request fails, retry anonymously.
144			// Some Nexus instances allow anonymous read of the group admin endpoint.
145			// A refused redirect to another origin is not such a failure: the
146			// detection stops there (DEVDESK-412), no silent anonymous retry.
147			if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
148				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
149				body, err = n.nexusGET(ctx, endpoint, anonInfo)
150			}
151		}
152		if errors.Is(err, oci.ErrOffOriginRedirect) {
153			// The advice below is for an account Nexus refused, not for this.
154			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
155			return nil
156		}
157		if err != nil {
158			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
159			return nil
160		}
161		var result struct {
162			Group struct {
163				MemberNames []string `json:"memberNames"`
164			} `json:"group"`
165		}
166		if err := json.Unmarshal(body, &result); err != nil {
167			return nil
168		}
169		return memberList(info.URL, result.Group.MemberNames)
170	}
171	
172	// memberList turns the names a group declares into addresses.
173	func memberList(dockerURL string, names []string) []GroupMember {
174		members := make([]GroupMember, 0, len(names))
175		for _, name := range names {
176			url, prefix := memberAddress(dockerURL, name)
177			members = append(members, GroupMember{
178				Alias:      cleanMemberAlias(name),
179				URL:        url,
180				RepoPrefix: prefix,
181			})
182		}
183		return members
184	}
185	
186	// memberAddress decides how one member of a group is reached, from the URL the
187	// group itself is pulled from.
188	//
189	// A group written as a path prefix — `host/repository/<group>` — is an instance
190	// serving its Docker repositories that way, so its members are reached the same
191	// way: the host, with the member's name in front of the repository. That pair is
192	// consistent by construction, because browse and pull build the same path from
193	// it.
194	//
195	// Anything else is a connector of the group's own — a dedicated port, a
196	// subdomain — and says nothing about a member. Which of those a repository
197	// answers on is a setting on that repository (`docker.httpPort`,
198	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
199	// refused to an ordinary pull account. So nothing is claimed: the member is
200	// offered at the group's own address with no prefix, which browses to nothing
201	// visibly rather than pulling to nothing plausibly (§3.18).
202	func memberAddress(dockerURL, memberName string) (url, prefix string) {
203		host, _, err := parseNexusURL(dockerURL)
204		if err != nil {
205			return dockerURL, ""
206		}
207		// parseNexusURL supplies https:// for a URL written without a scheme. The
208		// group's own spelling is what the rest of the application is keyed on, so
209		// it is kept rather than normalised here.
210		if !strings.Contains(strings.ToLower(dockerURL), "://") {
211			host = strings.TrimPrefix(host, "https://")
212		}
213		return host, memberName
214	}
215	
216	// nexusGET performs an authenticated GET and returns the response body.
217	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
218		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
219		if err != nil {
220			return nil, err
221		}
222		if info.Username != "" && info.Password != "" {
223			req.SetBasicAuth(info.Username, info.Password)
224		}
225		resp, err := nexusHTTPClient.Do(req)
226		if err != nil {
227			// A refused redirect comes back without the URL it pointed to, which
228			// may be signed.
229			return nil, oci.StripRedirectTarget(err)
230		}
231		defer func() { _ = resp.Body.Close() }()
232		if resp.StatusCode != http.StatusOK {
233			return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
234		}
235		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
236		if err != nil {
237			return nil, fmt.Errorf("read Nexus response: %w", err)
238		}
239		return body, nil
240	}
241	
242	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
243	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
244	func parseNexusURL(registryURL string) (host, repoName string, err error) {
245		raw := registryURL
246		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
247			raw = "https://" + raw
248		}
249		u, err := url.Parse(raw)
250		if err != nil {
251			return "", "", err
252		}
253		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
254		// Expected: ["repository", "<repoName>", ...]
255		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
256			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
257		}
258		host = u.Scheme + "://" + u.Host
259		repoName = parts[1]
260		return host, repoName, nil
261	}
262	
263	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
264	func cleanMemberAlias(name string) string {
265		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
266			if strings.HasSuffix(name, suffix) {
267				return name[:len(name)-len(suffix)]
268			}
269		}
270		return name
271	}
