19	// DEVDESK-509 (NX-06): the Nexus REST client reports a refused status as the
20	// typed oci.StatusError of the registry clients, keeps context errors as context
21	// errors, and treats a reply that is not a repository document as a failed
22	// discovery rather than as "not a group".
23	
24	// nexusServer starts a Nexus-like server and returns the registry the detector
25	// is asked about, plus a counter of the requests the server received. The
26	// handler is the server's, so a test decides what each endpoint answers.
27	func nexusServer(t *testing.T, h http.HandlerFunc) (RegistryInfo, *atomic.Int32) {
28		t.Helper()
29		var hits atomic.Int32
30		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
31			hits.Add(1)
32			h(w, r)
33		}))
34		t.Cleanup(srv.Close)
35		return RegistryInfo{
36			Provider: ProviderNexus,
37			URL:      srv.URL + "/repository/docker-group",
38			Username: nexusTestUser,
39			Password: REDACTED,
40		}, &hits
41	}
42	
43	// blockUntilGone holds a handler until the client hangs up or the test ends, so
44	// a test server never sleeps for an unbounded time (the server's Close waits for
45	// its handlers). release is closed by a cleanup registered after the server's,
46	// which therefore runs before the server's Close.
47	func blockUntilGone(t *testing.T, r *http.Request) {
48		t.Helper()
49		release := make(chan struct{})
50		t.Cleanup(func() { close(release) })
51		select {
52		case <-r.Context().Done():
53		case <-release:
54		}
55	}
56	
57	// wantContextError fails unless err is the given context error and is not a
58	// status error: a cancelled or expired call is not something Nexus answered.
59	func wantContextError(t *testing.T, err, want error) {
60		t.Helper()
61		if err == nil {
62			t.Fatalf("err = nil, want errors.Is %v", want)
63		}
64		if !errors.Is(err, want) {
65			t.Errorf("err = %v, want errors.Is %v", err, want)
66		}
67		var se *oci.StatusError
68		if errors.As(err, &se) {
69			t.Errorf("err = %v, is a *oci.StatusError (code %d), want a context error only", err, se.Code)
70		}
71	}
