130	// 3. A password written in the registry URL goes out of nobody's mouth: the
131	// error names the endpoint without the userinfo.
132	func TestNexusPasswordInTheURLIsNotInTheStatusError(t *testing.T) {
133		logs := nexusLog(t)
134		info, _ := nexusServer(t, func(w http.ResponseWriter, _ *http.Request) {
135			w.WriteHeader(http.StatusUnauthorized)
136		})
137		const user, pass = "alice", "S3CRETPW"
138		info.Username, info.Password = "", ""
139		info.URL = strings.Replace(info.URL, "http://", "http://"+user+":"+pass+"@", 1)
140	
141		_, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
142	
143		if err == nil {
144			t.Fatal("err = nil, want a status error")
145		}
146		var se *oci.StatusError
147		if !errors.As(err, &se) || se.Code != http.StatusUnauthorized || se.Source != oci.SourceManagementAPI {
148			t.Fatalf("err = %v, want a *oci.StatusError{401, SourceManagementAPI}", err)
149		}
150		for what, s := range map[string]string{"error": err.Error(), "log": logs.String()} {
151			for _, leak := range []string{user, pass} {
152				if strings.Contains(s, leak) {
153					t.Errorf("%s leaks %q: %s", what, leak, s)
154				}
155			}
156		}
157	}
