159	// 4. A context cancelled before the call never reaches the server and is not a
160	// status error.
161	func TestNexusCancelledContextIsNotAStatusError(t *testing.T) {
162		info, hits := nexusServer(t, func(w http.ResponseWriter, _ *http.Request) {
163			_, _ = io.WriteString(w, nexusGroupNoMembers)
164		})
165		ctx, cancel := context.WithCancel(context.Background())
166		cancel()
167	
168		members, err := (&NexusDetector{}).DetectGroup(ctx, info)
169	
170		wantContextError(t, err, context.Canceled)
171		if len(members) != 0 {
172			t.Errorf("members = %v, want none", members)
173		}
174		if got := hits.Load(); got != 0 {
175			t.Errorf("the server received %d requests, want 0", got)
176		}
177	}
