179	// 4. A deadline that expires while the server is silent is a deadline error,
180	// not a status error.
181	func TestNexusDeadlineIsNotAStatusError(t *testing.T) {
182		info, _ := nexusServer(t, func(_ http.ResponseWriter, r *http.Request) {
183			blockUntilGone(t, r)
184		})
185		ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
186		defer cancel()
187	
188		members, err := (&NexusDetector{}).DetectGroup(ctx, info)
189	
190		wantContextError(t, err, context.DeadlineExceeded)
191		if len(members) != 0 {
192			t.Errorf("members = %v, want none", members)
193		}
194	}
